create function pg_temp.config() returns jsonb language sql as $$select '{"tenantId":"65000000-0000-4000-8000-000000000002","locale":"en-US","timezone":"UTC","sender":{"emailFrom":"owner@example.test","smsFrom":"+12065550123"},"events":[{"event":"booking.confirmed","channels":["email"]}],"reminders":[],"templates":[{"trigger":"booking.confirmed","channel":"email","locale":"en-US","subject":"Booking {{bookingReference}}","body":"Hello {{customerName}}"}]}'::jsonb$$;
create function pg_temp.save(c jsonb default pg_temp.config(),r bigint default 0,a uuid default '65000000-0000-4000-8000-000000000001',t uuid default '65000000-0000-4000-8000-000000000002') returns jsonb language sql as $$select public.save_notification_planner_config(a,t,r,c)$$;
select pg_temp.assert((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.tenant_notification_planner_configs'::regclass),'forced RLS');
