select pg_temp.assert(not has_function_privilege('anon','public.save_notification_planner_config(uuid,uuid,bigint,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.owner_notification_planner_config(uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.save_notification_planner_config(uuid,uuid,bigint,jsonb)','EXECUTE'),'fixed service RPC grants');
