select pg_temp.assert(not has_function_privilege('anon','public.runtime_notification_planner_config(uuid)','EXECUTE') and not has_function_privilege('authenticated','public.runtime_notification_planner_config(uuid)','EXECUTE') and has_function_privilege('service_role','public.runtime_notification_planner_config(uuid)','EXECUTE'),'runtime fixed RPC grants');
